<?php
namespace CloudHost247\Ovh\Services;use WHMCS\Database\Capsule;use RuntimeException;
final class Provisioner
{private$r;function __construct(ConnectionResolver$r){$this->r=$r;}function provision($serviceId,$productId,array$options=array()){$mapping=(new MappingRepository())->forProduct($productId);if(!$mapping)throw new RuntimeException('No active OVH mapping for this product.');$existing=Capsule::table('mod_cloudhost247_ovh_services')->where('whmcs_service_id',(int)$serviceId)->first();if($existing&&in_array($existing->status,array('ordering','pending','active'),true))return array('status'=>$existing->status,'order_id'=>$existing->remote_order_id,'idempotent'=>true);$key=hash('sha256','provision:'.(int)$serviceId.':'.$mapping->id);try{Capsule::table('mod_cloudhost247_ovh_operations')->insert(array('whmcs_service_id'=>$serviceId,'operation'=>'provision','idempotency_key'=>$key,'status'=>'running','request_json'=>json_encode(array('mapping_id'=>$mapping->id)),'attempts'=>1,'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')));}catch(\Throwable$e){$op=Capsule::table('mod_cloudhost247_ovh_operations')->where('idempotency_key',$key)->first();if($op&&in_array($op->status,array('running','success'),true))return array('status'=>$op->status,'remote_id'=>$op->remote_id,'idempotent'=>true);throw$e;}Capsule::table('mod_cloudhost247_ovh_services')->updateOrInsert(array('whmcs_service_id'=>$serviceId),array('endpoint_id'=>$mapping->endpoint_id,'family'=>$mapping->family,'status'=>'ordering','updated_at'=>date('Y-m-d H:i:s')));$client=$this->r->endpoint($mapping->endpoint_id);try{$config=json_decode($mapping->configuration_json,true)?:array();$service=Capsule::table('mod_cloudhost247_ovh_services')->where('whmcs_service_id',$serviceId)->first();$details=json_decode($service->details_json?:'{}',true)?:array();if(empty($details['cart_id'])){$cart=$client->post('/order/cart',array('ovhSubsidiary'=>$mapping->subsidiary));if(empty($cart['cartId']))throw new RuntimeException('OVH did not return a cart ID.');$details['cart_id']=$cart['cartId'];Capsule::table('mod_cloudhost247_ovh_services')->where('id',$service->id)->update(array('details_json'=>json_encode($details),'updated_at'=>date('Y-m-d H:i:s')));$client->post('/order/cart/'.rawurlencode($cart['cartId']).'/assign',array());}$route=$config['order_route']??($mapping->family==='vps'?'vps':'eco');if(!in_array($route,array('eco','vps','baremetalServers'),true))throw new RuntimeException('Unsupported OVH order route.');if(empty($details['item_id'])){$item=$client->post('/order/cart/'.rawurlencode($details['cart_id']).'/'.$route,array('duration'=>$config['duration']??'P1M','planCode'=>$mapping->plan_code,'pricingMode'=>$config['pricing_mode']??'default','quantity'=>1));if(empty($item['itemId']))throw new RuntimeException('OVH did not return a cart item ID.');$details['item_id']=$item['itemId'];Capsule::table('mod_cloudhost247_ovh_services')->where('id',$service->id)->update(array('details_json'=>json_encode($details),'updated_at'=>date('Y-m-d H:i:s')));foreach(($config['configurations']??array()) as$c){if(!isset($c['label'],$c['value']))continue;$client->post('/order/cart/'.rawurlencode($details['cart_id']).'/item/'.rawurlencode($details['item_id']).'/configuration',array('label'=>$c['label'],'value'=>$c['value']));}}$checkout=$client->post('/order/cart/'.rawurlencode($details['cart_id']).'/checkout',array('autoPayWithPreferredPaymentMethod'=>false),false);$order=(string)($checkout['orderId']??'');if($order==='')throw new RuntimeException('OVH checkout did not return an order ID.');Capsule::table('mod_cloudhost247_ovh_services')->where('whmcs_service_id',$serviceId)->update(array('remote_order_id'=>$order,'status'=>'pending','details_json'=>json_encode($details),'updated_at'=>date('Y-m-d H:i:s')));Capsule::table('mod_cloudhost247_ovh_operations')->where('idempotency_key',$key)->update(array('status'=>'success','remote_id'=>$order,'response_json'=>json_encode($checkout),'updated_at'=>date('Y-m-d H:i:s')));return array('status'=>'pending','order_id'=>$order,'idempotent'=>false);}catch(\Throwable$e){Capsule::table('mod_cloudhost247_ovh_operations')->where('idempotency_key',$key)->update(array('status'=>'failed','error_message'=>substr($e->getMessage(),0,1000),'updated_at'=>date('Y-m-d H:i:s')));throw$e;}}
}
